import json
from pathlib import Path

def compute_brief_status(repo_root: Path, state_dir: Path) -> list[dict]:
    results = []

    for brief_path in repo_root.glob("brief_hooks_*.md"):
        filename = brief_path.name
        slug = filename[len("brief_hooks_"):-len(".md")]

        plan_path = repo_root / f"plan_hooks_{slug}.json"
        has_plan = plan_path.exists()

        if not has_plan:
            results.append({
                "slug": slug,
                "state": "unplanned",
                "has_plan": False
            })
        else:
            try:
                plan_data = json.loads(plan_path.read_text(encoding="utf-8"))
                tasks = plan_data.get("tasks", [])
            except Exception:
                tasks = []

            task_ids = [t.get("task_id") for t in tasks if "task_id" in t]

            progress_path = state_dir / "impl_progress.jsonl"
            accepted_tasks = set()
            if progress_path.exists():
                with open(progress_path, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            record = json.loads(line)
                            if record.get("phase") == "accepted" and "task_id" in record:
                                accepted_tasks.add(record["task_id"])
                        except Exception:
                            pass

            remaining = [t for t in task_ids if t not in accepted_tasks]
            state = "complete" if not remaining else "planned"

            results.append({
                "slug": slug,
                "state": state,
                "has_plan": True,
                "remaining": remaining
            })

    results.sort(key=lambda x: x["slug"])
    return results

